-- crescent_grove: map 802, 5 legs, 561 steps
DELETE FROM `ai_dungeon_step` WHERE `plan` = 'crescent_grove';
DELETE FROM `ai_dungeon_leg` WHERE `plan` = 'crescent_grove';
DELETE FROM `ai_dungeon_plan` WHERE `plan` = 'crescent_grove';

-- Map 802's boss table rows: the five boss steps' creatures (rank 1, elite; no instance bind). The DELETE is scoped to this
-- plan's own entries: no other plan shares map 802, and a whole-map delete would be a loaded gun for the next one.
DELETE FROM `ai_dungeon_boss` WHERE `map` IN (802) AND `entry` IN (92107, 92109, 92108, 92111, 92110);
